LEGACY_RECORDS = [{'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP5/demand.csv', 'values': {'customer': 'C1', 'demand': '143'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP5/demand.csv', 'values': {'customer': 'C2', 'demand': '6'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP5/demand.csv', 'values': {'customer': 'C3', 'demand': '10'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP5/demand.csv', 'values': {'customer': 'C4', 'demand': '25'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP5/demand.csv', 'values': {'customer': 'C5', 'demand': '3'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP5/fixed_cost.csv', 'values': {'Unnamed: 0': 'S1', 'fixed_costs': '97.65000000000001'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP5/fixed_cost.csv', 'values': {'Unnamed: 0': 'S2', 'fixed_costs': '99.76000000000001'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP5/fixed_cost.csv', 'values': {'Unnamed: 0': 'S3', 'fixed_costs': '100.76'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP5/fixed_cost.csv', 'values': {'Unnamed: 0': 'S4', 'fixed_costs': '105.32'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP5/fixed_cost.csv', 'values': {'Unnamed: 0': 'S5', 'fixed_costs': '98.88'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP5/transportation_costs.csv', 'values': {'Unnamed: 0': 'S1', 'C1': '150.74', 'C2': '0.02', 'C3': '49.13', 'C4': '2080.15', 'C5': '426.4'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP5/transportation_costs.csv', 'values': {'Unnamed: 0': 'S2', 'C1': '233.05', 'C2': '97.73', 'C3': '49.84', 'C4': '1982.39', 'C5': '23.96'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP5/transportation_costs.csv', 'values': {'Unnamed: 0': 'S3', 'C1': '55.68', 'C2': '935.61', 'C3': '4.03', 'C4': '73.09', 'C5': '525.3200000000001'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP5/transportation_costs.csv', 'values': {'Unnamed: 0': 'S4', 'C1': '1483.82', 'C2': '1801.08', 'C3': '112.16', 'C4': '816.05', 'C5': '107.01'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP5/transportation_costs.csv', 'values': {'Unnamed: 0': 'S5', 'C1': '1119.47', 'C2': '884.3099999999999', 'C3': '0.08', 'C4': '1544.95', 'C5': '543.67'}}]
import gurobipy as gp
from gurobipy import GRB
demand = {}
fixed_cost = {}
transport_cost = {}
suppliers = []
branches = []
for rec in LEGACY_RECORDS:
    src = rec['source']
    vals = rec['values']
    if src.endswith('demand.csv'):
        cust = vals['customer']
        demand[cust] = float(vals['demand'])
        if cust not in branches:
            branches.append(cust)
    elif src.endswith('fixed_cost.csv'):
        sup = vals['Unnamed: 0']
        fixed_cost[sup] = float(vals['fixed_costs'])
        if sup not in suppliers:
            suppliers.append(sup)
    elif src.endswith('transportation_costs.csv'):
        sup = vals['Unnamed: 0']
        if sup not in suppliers:
            suppliers.append(sup)
        if sup not in transport_cost:
            transport_cost[sup] = {}
        for b in vals:
            if b == 'Unnamed: 0':
                continue
            transport_cost[sup][b] = float(vals[b])
            if b not in branches:
                branches.append(b)
for b in branches:
    if b not in demand:
        raise ValueError(f'Missing demand for branch {b}')
for s in suppliers:
    if s not in fixed_cost:
        raise ValueError(f'Missing fixed cost for supplier {s}')
    if s not in transport_cost:
        raise ValueError(f'Missing transport cost row for supplier {s}')
    for b in branches:
        if b not in transport_cost[s]:
            raise ValueError(f'Missing transport cost for supplier {s}, branch {b}')
M = {(i, j): demand[j] for i in suppliers for j in branches}
m = gp.Model('Superstore_UFLP')
y_vars = m.addVars(suppliers, vtype=GRB.BINARY, name='')
x_vars = m.addVars(suppliers, branches, lb=0, vtype=GRB.CONTINUOUS, name='')
m.setObjective(gp.quicksum((fixed_cost[i] * y_vars[i] for i in suppliers)) + gp.quicksum((transport_cost[i][j] * x_vars[i, j] for i in suppliers for j in branches)), GRB.MINIMIZE)
m.addConstrs((gp.quicksum((x_vars[i, j] for i in suppliers)) >= demand[j] for j in branches), name='')
m.addConstrs((x_vars[i, j] <= M[i, j] * y_vars[i] for i in suppliers for j in branches), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')